import{_ as l,l as n,o as e,c as i,v as o,p,x as t,d as s,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"隔夜 / 日内 alpha","description":"","frontmatter":{"title":"隔夜 / 日内 alpha","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/overnight-intraday-alpha.md","filePath":"quant/overnight-intraday-alpha.md","lastUpdated":1789023840000}'),E={name:"quant/overnight-intraday-alpha.md"};function c(u,a,m,A,B,_){const r=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=o('<h1 id="隔夜-日内-alpha" tabindex="-1">隔夜 / 日内 alpha <a class="header-anchor" href="#隔夜-日内-alpha" aria-label="Permalink to &quot;隔夜 / 日内 alpha&quot;">​</a></h1><div class="epigraph"><p>把收盘到收盘拆开之后，许多异象的利润几乎全部发生在隔夜，日内则在做反向的拔河；谁在开盘交易、谁在盘中交易，决定了 alpha 写在哪一段。</p><footer>—— Lou, Polk &amp; Skouras, A Tug of War: Overnight Versus Intraday Expected Returns, Journal of Financial Economics, 2019</footer></div><p>日收益默认是一块。拆成<strong>隔夜</strong>（close-to-open）与<strong>日内</strong>（open-to-close）之后，均值、因子暴露与异常利润可以对得很不对称。Lou、Polk、Skouras（2019）系统展示：美股上市场溢价与动量等策略的收益集中在隔夜，日内往往弱、零甚至为负；隔夜与日内收益之间存在负相关的「拔河」。这与本站 <a href="/quant/calendar-overnight">日历与隔夜</a> 的制度分解衔接，但对象从「一天不像一天」推进到「异常收益住在哪一段时钟」。客户结构是候选机制：个人更影响开盘附近的持仓跨越，机构在盘中提供反向价格压力。本篇写分解口径、Lou 等的主要事实，以及把隔夜 alpha 当成可交易信号时会踩的拍卖与前视陷阱。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若收益在连续交易的半鞅里均匀产生，隔夜只是一段不可交易的时间，均值应按方差或按日历长度摊。事实不是这样：隔夜方差大，但更惊人的是<strong>均值的分配</strong>——不少样本里股权风险溢价主要出现在隔夜，日内平均接近零。对异常更尖锐：动量的 WML 利润可以几乎全是隔夜的，日内动量甚至为负；某些反转、某些微观结构策略则主要在日内。若仍用收盘到收盘评价因子，会把两段符号相反的现金流捆成一个 α，既高估可实现性（隔夜无法用盘中算法去「赚」），也误导关于谁在提供错误定价的推断。</p><p>需要同时回答三个测量问题。价格用哪一个：官方收盘、收盘拍卖、开盘拍卖还是开盘后短窗口中点？间隔如何处理周末与假日？因子组合是用收盘价排序、再用隔夜收益评价，还是开盘就重做信号？第三个问题决定有没有前视：用今天收盘的 MAX 去「解释」昨夜的隔夜收益，是把结果当原因。</p><h3 id="拔河-隔夜与日内的负相关" tabindex="-1">拔河：隔夜与日内的负相关 <a class="header-anchor" href="#拔河-隔夜与日内的负相关" aria-label="Permalink to &quot;拔河：隔夜与日内的负相关&quot;">​</a></h3><p>Lou 等把个股或组合的隔夜收益与随后日内收益放在一起，观察到负相关：隔夜涨得多的，日内更容易回吐，反之亦然。这不是简单的买卖价差弹跳——弹跳会在极短窗口消失——而是开盘附近的客户流与盘中客户流方向相反的持久模式。个人在收盘附近或隔夜消息后更可能成为净需求，把价格推过隔夜；机构在日内把价格推回去。组合层面的拔河意味着：只持有隔夜、在开盘平仓的纸面策略，会把机构在日内提供的负 alpha 丢掉；全日持有则把两段对冲掉一部分。评价必须分段报，不能只报净的收盘到收盘。</p><p><span class="marginnote">开盘拍卖把隔夜信息的很大一块写进开盘价。于是「隔夜收益」含价格发现，不只是闭市跳空。口径若改成开盘后 30 分钟相对昨日收盘，隔夜溢价的大小和归属的策略都会变。比较论文必须先对齐价格定义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对每个交易日 \\(d\\)，</p> \\[R_d^{\\mathrm{c2c}}=R_d^{\\mathrm{c2o}}+R_d^{\\mathrm{o2c}}, \\]<p>在算术收益下近似成立（对数收益则精确可加）。对因子组合，用\\(t-1\\) 收盘可获得的信号决定持仓，分别累加 \\(t\\) 的隔夜与 \\(t\\) 的日内。市场因子本身也要拆：隔夜市场收益与日内市场收益，估计两套 β。Lou 等的核心表是：各异象组合的平均隔夜收益、平均日内收益、以及两者之差。动量、盈利等偏「隔夜」；短期反转、某些流动性提供偏「日内」。国际样本与 ETF 上应单独做，因为开盘机制不同。</p><p>执行约束要写进方法，而不是脚注。隔夜 alpha 若只能通过在收盘买、开盘卖来实现，则两边都撞上拍卖与流动性最差的时段，冲击成本可以吃掉账面均值。用期货或 ADR 的夜盘去复制「隔夜」改变了信息集：夜盘已经是连续交易，不再是 Lou 等的美股现货闭市。A 股有午休、T+1、集合竞价，隔夜与日内的切分多一段午休，不能直接套用美股表格的符号。</p><h3 id="信号时钟必须与收益时钟一致" tabindex="-1">信号时钟必须与收益时钟一致 <a class="header-anchor" href="#信号时钟必须与收益时钟一致" aria-label="Permalink to &quot;信号时钟必须与收益时钟一致&quot;">​</a></h3><p>用收盘价算 12−1 动量，持有到下月收盘，隔夜利润来自「收盘后到次日开盘」的一段重复许多次。若有人用开盘价重做排序，再去收隔夜收益，信号含开盘信息，隔夜不再是未被信号使用的区间。MAX、IVOL 尤其危险：它们由日收益构成，若日收益含今天隔夜，再用这个 MAX 去预测今天隔夜，部分是同期。正确的是：特征在 \\(t\\) 收盘锁定，预测 \\(t\\) 到 \\(t+1\\) 的隔夜与 \\(t+1\\) 的日内。财报盘后发布会把信息写进隔夜，PEAD 的隔夜腿会特别强——这是信息释放制度，不是动量的同一机制，应单独标记公告日。</p>',16)),(e(),p(d,null,{default:t(()=>[h(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIG%5B%22t%E2%88%921%20%E6%94%B6%E7%9B%98%E9%94%81%E5%AE%9A%E4%BF%A1%E5%8F%B7%22%5D%20--%3E%20HOLD%5B%22%E6%8C%81%E4%BB%93%E8%B7%A8%E8%B6%8A%E9%97%AD%E5%B8%82%22%5D%0A%20%20HOLD%20--%3E%20ON%5B%22%E9%9A%94%E5%A4%9C%20c2o%22%5D%0A%20%20HOLD%20--%3E%20ID%5B%22%E6%97%A5%E5%86%85%20o2c%22%5D%0A%20%20ON%20--%3E%20CLI%5B%22%E5%BC%80%E7%9B%98%E5%AE%A2%E6%88%B7%E6%B5%81%20%2F%20%E6%8B%8D%E5%8D%96%22%5D%0A%20%20ID%20--%3E%20INST%5B%22%E7%9B%98%E4%B8%AD%E6%9C%BA%E6%9E%84%E5%8F%8D%E5%90%91%22%5D%0A%20%20ON%20--%3E%20TOW%5B%22%E6%8B%94%E6%B2%B3%EF%BC%9A%E9%9A%94%E5%A4%9C%E4%B8%8E%E6%97%A5%E5%86%85%E8%B4%9F%E7%9B%B8%E5%85%B3%22%5D%0A%20%20ID%20--%3E%20TOW%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>客户结构是 Lou 等强调的通道。个人投资者相对更可能把持仓留过隔夜、更可能在开盘附近交易注意力股票；机构的算法与再平衡集中在连续竞价。于是需要隔夜风险补偿的那一侧（或被注意力推高的那一侧）把正的期望写在 c2o；日内则出现反向的价格压力。动量的隔夜集中符合「赢家被个人愿意隔夜持有、开盘仍有需求」；日内为负符合「机构在盘中卖出相对高估」。这与 <a href="/quant/max-effect">MAX</a> 的彩票需求、与 BW 情绪的零售投机可以接到同一条客户链上，但频率不同：情绪是月与年，隔夜/日内是每个交易日的两段。</p><p>风险补偿叙事：不可交易时段无法对冲，隔夜应有溢价。它解释市场的隔夜均值，解释不了为什么有的异常在日内、有的在隔夜，除非不同股票的隔夜不可对冲性不同。微观结构叙事：收盘拍卖与开盘拍卖的设计、做市商隔夜存货，会把价差与跳空写成均值。它预测小盘、宽价差股票的「隔夜 alpha」更脏。稳健做法是在大盘、可投资宇宙上重做分段，看符号是否还在——Lou 等的部分结果在大盘上仍然存在，说明不只是微型股弹跳。</p><h3 id="与因子模型、执行算法的接口" tabindex="-1">与因子模型、执行算法的接口 <a class="header-anchor" href="#与因子模型、执行算法的接口" aria-label="Permalink to &quot;与因子模型、执行算法的接口&quot;">​</a></h3><p>四因子、五因子若只用收盘到收盘估计，β 是两段暴露的平均。一只股票可以隔夜高 β、日内低 β，全日回归看不出来。对冲若在日内做，对的是日内 β，隔夜腿仍裸露。隔夜缺口对冲是另一条目的问题；这里只需承认：alpha 的时钟不匹配对冲的时钟时，残差不是模型失败，是交易时段失败。执行算法（VWAP、TWAP）默认在日内把仓位摊完，恰好会<strong>丢掉</strong>隔夜 alpha、留下日内那一段——若日内是负的，VWAP 实现会系统性地差于收盘到收盘回测。这是研究到产品最常见的缺口之一。</p><p><span class="marginnote">纸面组合用收盘价成交。隔夜 alpha 的实现至少涉及收盘拍卖的参与与次日开盘的平仓或继续持有。拍卖里的冲击、未成交与价格改善，不会出现在 CRSP 收盘价回测里。分段报告若仍假设收盘价无冲击，只是把同一偏见拆成了两段。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要把期货夜盘收益叫做 Lou 等的隔夜：信息集与可交易性都变了。不要用第一根五分钟 K 线当开盘价去复制论文，除非声明。不要在 T+1 市场假设开盘卖出隔夜多头没有约束。不要把所有隔夜正收益都归因于散户：宏观公告、海外市场、指数期货在闭市时的价格发现同样写入开盘，这是公共信息的时钟，与客户结构可并存。拆公告日与非公告日是最低限度的识别。</p><p>容量：能稳定收取隔夜溢价的，是能够在拍卖中提供流动性或能够持有跨越、并承受开盘波动的资本。高频抢开盘不是本篇对象，也不是 Lou 等的识别策略。作为研究诊断，隔夜/日内分解极有价值——它告诉你异常更像持仓跨越的需求还是盘中的反向。作为交易规则，必须单独做拍卖冲击、隔夜跳空风险与对冲工具（若有夜盘衍生品）的成本，不能把 JFE 表格的年化隔夜收益写进产品说明书。</p><p>与日历效应的分工：周末、假日改变的是隔夜长度与信息积累，应单独报告周五收盘到周一开盘。把所有 c2o 平均在一起，会把周末效应摊进隔夜 alpha。French 的周末效应与 Lou 的策略分解是不同频率上的同一把刀：先切时钟，再谈定价。</p><p><span class="marginnote">出处：Lou, Polk &amp; Skouras, <em>Journal of Financial Economics</em>, 2019。日历与周末见 French, 1980 及本站日历条目。客户与开盘注意力见 Berkman 等开盘文献。不要用隔夜动量去替代 Jegadeesh–Titman 的月度 WML 出处。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>收盘到收盘应拆成隔夜与日内；许多异象（含动量）利润集中在隔夜，日内常弱或反向。</li><li>隔夜与日内存在拔河式负相关，指向不同客户在不同时段的方向。</li><li>信号必须在收益区间开始前锁定；开盘拍卖口径会改变「隔夜」的含义。</li><li>VWAP 类日内执行会系统性错过隔夜腿，使实现偏离全日回测。</li><li>夜盘衍生品、T+1、涨跌停会改写分段，不能直接套用美股现货结论。</li><li>出处：Lou, Polk &amp; Skouras, <em>JFE</em>, 2019。</li></ul>',13))])}const T=l(E,[["render",c]]);export{P as __pageData,T as default};
